@pytest.mark.parametrize("drift", [None, "factor", "base", "registry"]) def test_owned_qv_block_replay_guards_original_execution_objects(drift): wrapper = fake_wrapper() layer = fake_layer() layer.self_attn.config = LlamaConfig( hidden_size=576, num_attention_heads=9, num_key_value_heads=3, ) layer.self_attn.config._attn_implementation = "eager" wrapper.base = layer wrapper.train() for target in ("q", "v"): with torch.no_grad(): wrapper.reference.factors["29"][target].B.fill_(0.01) wrapper.enable_checkpoint_inventory() parameters = tuple(wrapper.reference.factors["29"].parameters()) hidden = torch.linspace(-1, 1, 1152).reshape(1, 2, 576) expected = live(wrapper, 29, layer, hidden) gradients = torch.autograd.grad(expected.square().sum(), parameters) operation = wrapper._bind_checkpoint_block(29, layer) calls = []
def block(value, metadata): calls.append(1) return operation(value, metadata)
def execute(): with wrapper.checkpoint_session() as session: ticket = session.begin_forward(wrapper, data()) output = hidden for index in range(30): # The first29 fixture blocks are identities; only the final q/v # block is exercised. This is not a full-host all-layer proof. output = ticket.run( index, block if index == 29 else lambda value, metadata: value, output, ) ticket.bind_output(output) if drift == "factor": parameters[-1].data.add_(1) elif drift == "base": layer.self_attn.v_proj.weight.data.add_(1) elif drift == "registry": wrapper.reference.factors["29"]["v"].B = torch.nn.Parameter( parameters[-1].detach().clone() ) session.backward(output.square().sum()) assert torch.equal(output, expected)
if drift is None: execute() assert len(calls) == 2 for parameter, gradient in zip(parameters, gradients, strict=True): assert torch.equal(parameter.grad, gradient) else: with pytest.raises(CheckpointExecutionError): execute() > assert len(calls) == 1 # Drift rejected before recomputation side effects. ^^^^^^^^^^^^^^^^^^^^^^ E assert 2 == 1 E + where 2 = len([1, 1])
